INSERT OR IGNORE INTO settings(key,value_json) VALUES('product_name','"Ứng dụng Nhà Hán Ngữ"');
INSERT OR IGNORE INTO settings(key,value_json) VALUES('facebook_url','"https://www.facebook.com/nhahanngu.vn"');
INSERT OR IGNORE INTO settings(key,value_json) VALUES('tiktok_url','"https://www.tiktok.com/@nhahanngu"');
INSERT OR IGNORE INTO settings(key,value_json) VALUES('hero_text','"Ứng dụng hoạt động, bảng tin, tham gia cộng đồng và xác thực GCN/GXN của Nhà Hán Ngữ."');
INSERT OR IGNORE INTO settings(key,value_json) VALUES('home_intro_title','"Một ứng dụng thống nhất cho cộng đồng Nhà Hán Ngữ"');
INSERT OR IGNORE INTO settings(key,value_json) VALUES('home_intro_text','"Ứng dụng Nhà Hán Ngữ được xây dựng như một điểm truy cập thống nhất cho hoạt động, bảng tin, biểu mẫu tham gia, hỗ trợ và xác thực GCN/GXN. Người dùng không cần hiểu cấu trúc kỹ thuật phía sau vẫn có thể nhanh chóng tìm đúng chức năng mình cần. Với đội ngũ vận hành, dữ liệu được tổ chức tập trung giúp giảm việc xử lý rời rạc và hạn chế sai lệch giữa nhiều nguồn thông tin. Ứng dụng ưu tiên trải nghiệm rõ ràng trên cả máy tính và điện thoại, đồng thời giữ các chức năng quản trị chuyên sâu ở khu vực riêng dành cho người có quyền truy cập."');
INSERT OR IGNORE INTO settings(key,value_json) VALUES('home_join_title','"Cùng học, cùng chia sẻ, cùng phát triển"');
INSERT OR IGNORE INTO settings(key,value_json) VALUES('home_join_text','"Nhà Hán Ngữ hướng đến một cộng đồng nơi người học không chỉ nhận nội dung mà còn có thể tham gia, trao đổi và đóng góp giá trị. Bạn có thể bắt đầu từ việc theo dõi hoạt động, đăng ký một chương trình, trở thành thành viên hoặc cộng tác viên, chia sẻ kinh nghiệm phù hợp hay gửi đề xuất cho đội ngũ vận hành. Mỗi hình thức tham gia có yêu cầu khác nhau và được công bố rõ trong biểu mẫu tương ứng. NHN khuyến khích sự chủ động, tôn trọng, tinh thần học hỏi và trách nhiệm với cộng đồng."');
INSERT OR IGNORE INTO settings(key,value_json) VALUES('about_title','"Nhà Hán Ngữ là gì?"');
INSERT OR IGNORE INTO settings(key,value_json) VALUES('about_body','"Nhà Hán Ngữ (NHN) được xây dựng như một không gian học tập và kết nối dành cho những người quan tâm đến tiếng Trung, Hán ngữ và các hoạt động phát triển cộng đồng. Thay vì chỉ tập trung vào một khóa học hoặc một kỳ thi, NHN hướng đến một môi trường mở, nơi người học có thể tiếp cận kiến thức, theo dõi hoạt động, tìm tài liệu phù hợp, tham gia chương trình và kết nối với những người có cùng mục tiêu.\n\nỨng dụng Nhà Hán Ngữ là một phần trong định hướng đó. Ứng dụng tập trung các chức năng cần thiết như bảng tin, hoạt động, biểu mẫu tham gia, hỗ trợ, quản lý hồ sơ và xác thực Giấy chứng nhận/Giấy xác nhận. Mục tiêu là giúp người dùng không phải tìm kiếm thông tin rải rác ở nhiều nơi, đồng thời giúp đội ngũ vận hành quản lý dữ liệu theo một quy trình thống nhất. Những phần dành cho cộng đồng được thiết kế đơn giản, dễ hiểu; những chức năng nghiệp vụ chuyên sâu được đặt trong khu vực quản trị.\n\nVề nội dung, Nhà Hán Ngữ định hướng phát triển các chủ đề từ nền tảng đến nâng cao như phát âm, từ vựng, ngữ pháp, chữ Hán, kỹ năng nghe – nói – đọc – viết, kiến thức HSK, HSKK, tài liệu tham khảo liên quan đến CSCA, văn hóa Trung Hoa và các hoạt động giao lưu học tập. NHN không tự nhận là cơ quan khảo thí chính thức. Với những thông tin liên quan đến quy chế thi, lịch thi hoặc yêu cầu hồ sơ có thể thay đổi, người học vẫn nên đối chiếu nguồn chính thức trước khi đưa ra quyết định.\n\nNhà Hán Ngữ hướng đến nhiều nhóm người dùng: người mới bắt đầu, học sinh – sinh viên, người đang tự học, người luyện thi, người muốn cải thiện khả năng giao tiếp và cả những cá nhân muốn đóng góp kiến thức hoặc kỹ năng cho cộng đồng. Một người có thể bắt đầu bằng việc đọc một bài viết, tham gia một hoạt động, đăng ký làm cộng tác viên hoặc đơn giản là theo dõi các kênh của NHN. Không có một con đường duy nhất để trở thành một phần của cộng đồng.\n\nNHN hoạt động trong hệ sinh thái Mạng lưới Giáo dục & Phát triển Cộng đồng Sky First (SFN). Việc có một ứng dụng riêng giúp Nhà Hán Ngữ giữ được không gian vận hành phù hợp với đặc thù của mình, nhưng vẫn có thể liên thông với hệ thống tổng hợp của Sky First khi cần. Ví dụ, API tra cứu GCN/GXN của Nhà Hán Ngữ được duy trì để hệ thống tại skyfirst.io.vn có thể xác thực trực tiếp từ dữ liệu gốc thay vì sao chép bản ghi sang một cơ sở dữ liệu khác.\n\nĐiều NHN hướng đến không phải là tạo ra một nền tảng nhiều tính năng nhưng khó sử dụng. Giá trị thực tế nằm ở việc người dùng tìm đúng thông tin nhanh hơn, hiểu rõ cách tham gia, nhận được hỗ trợ khi cần và có thể kiểm tra thông tin minh bạch. Ứng dụng vì vậy được phát triển theo nguyên tắc giao diện công khai rõ ràng, dữ liệu tập trung, quyền quản trị minh bạch và khả năng mở rộng theo nhu cầu thực tế.\n\nNhà Hán Ngữ tin rằng một cộng đồng học tập tốt không chỉ được tạo nên bởi nội dung, mà còn bởi những kết nối có giá trị. Mỗi bài học, mỗi trải nghiệm, mỗi lần chia sẻ và mỗi hoạt động đều có thể trở thành một phần của hành trình dài hơn. NHN mong muốn tiếp tục xây dựng môi trường để những bước nhỏ đó được kết nối với nhau theo cách tích cực, thiết thực và bền vững."');
INSERT OR IGNORE INTO settings(key,value_json) VALUES('support_title','"Hỗ trợ & phản hồi"');
INSERT OR IGNORE INTO settings(key,value_json) VALUES('support_body','"Khu vực Hỗ trợ & phản hồi được xây dựng để người dùng có một đầu mối rõ ràng khi cần trợ giúp trong quá trình sử dụng Ứng dụng Nhà Hán Ngữ hoặc tham gia các hoạt động của NHN. Bạn có thể gửi yêu cầu khi gặp vấn đề với biểu mẫu đăng ký, không tra cứu được hồ sơ, cần xác minh thông tin GCN/GXN, phát hiện dữ liệu chưa chính xác, gặp lỗi kỹ thuật hoặc muốn đóng góp ý kiến để hệ thống hoạt động tốt hơn.\n\nKhi gửi yêu cầu, bạn nên cung cấp thông tin vừa đủ để đội ngũ phụ trách có thể kiểm tra. Với hồ sơ đăng ký, hãy ghi mã hồ sơ nếu đã được cấp. Với GCN/GXN, hãy cung cấp mã phát hành được hiển thị trên văn bản. Nếu phản ánh lỗi giao diện, bạn có thể mô tả thiết bị, trình duyệt và thao tác đã thực hiện trước khi lỗi xuất hiện. Không nên gửi mật khẩu, mã xác thực hai bước, khóa bảo mật hoặc các thông tin bí mật khác qua biểu mẫu hỗ trợ.\n\nNhà Hán Ngữ ưu tiên xử lý yêu cầu dựa trên tính chất và mức độ ảnh hưởng. Những vấn đề liên quan đến quyền truy cập, sai lệch dữ liệu cá nhân, trạng thái GCN/GXN hoặc lỗi khiến người dùng không thể hoàn tất thao tác sẽ được xem xét trước. Các góp ý về nội dung, giao diện hoặc đề xuất tính năng được ghi nhận để cân nhắc trong quá trình phát triển. Việc gửi góp ý không đồng nghĩa mọi đề xuất đều được triển khai ngay, nhưng các phản hồi có căn cứ giúp đội ngũ hiểu rõ hơn nhu cầu thực tế của cộng đồng.\n\nĐối với tra cứu GCN/GXN, hệ thống công khai chỉ nên được sử dụng để đối chiếu những thông tin cần thiết. Nếu mã không trả về kết quả, trước tiên hãy kiểm tra lại ký tự, dấu gạch và định dạng. Nếu vẫn không có kết quả nhưng bạn có căn cứ cho rằng văn bản đã được phát hành, hãy gửi yêu cầu hỗ trợ kèm mã để đội ngũ kiểm tra dữ liệu nguồn. Trạng thái thu hồi hoặc thay đổi hiệu lực, nếu có, sẽ được phản ánh theo bản ghi trong hệ thống.\n\nNhà Hán Ngữ cũng tiếp nhận phản hồi về an toàn và quyền riêng tư. Nếu bạn nhận thấy một trang hiển thị thông tin không phù hợp, một tệp bị chia sẻ sai phạm vi hoặc một tài khoản có dấu hiệu truy cập trái phép, hãy báo ngay để được kiểm tra. Không nên đăng công khai dữ liệu nhạy cảm trên mạng xã hội chỉ để yêu cầu hỗ trợ; sử dụng biểu mẫu hoặc email sẽ giúp thông tin được chuyển đến đúng người xử lý hơn.\n\nBạn có thể sử dụng nút “Gửi yêu cầu hỗ trợ” trên trang này hoặc liên hệ qua email nhahanngu.vn@gmail.com. Các kênh Facebook và TikTok của Nhà Hán Ngữ phù hợp để theo dõi thông tin cộng đồng, nhưng những yêu cầu cần đối chiếu dữ liệu nên được gửi qua kênh hỗ trợ chính thức để có đủ thông tin xử lý.\n\nMục tiêu của hệ thống hỗ trợ là giúp việc trao đổi trở nên rõ ràng, có thể theo dõi và hạn chế tình trạng người dùng phải nhắn nhiều nơi cho cùng một vấn đề. Mỗi phản hồi phù hợp đều là một nguồn dữ liệu giúp ứng dụng tiếp tục được cải thiện theo nhu cầu thật của cộng đồng."');
INSERT OR IGNORE INTO news(id,title,slug,body,status,published_at) VALUES('NEWS-APP-2026','Ứng dụng Nhà Hán Ngữ: một không gian số thống nhất cho cộng đồng','ung-dung-nha-han-ngu-2026','Nhà Hán Ngữ (NHN) được xây dựng như một không gian học tập và kết nối dành cho những người quan tâm đến tiếng Trung, Hán ngữ và các hoạt động phát triển cộng đồng. Thay vì chỉ tập trung vào một khóa học hoặc một kỳ thi, NHN hướng đến một môi trường mở, nơi người học có thể tiếp cận kiến thức, theo dõi hoạt động, tìm tài liệu phù hợp, tham gia chương trình và kết nối với những người có cùng mục tiêu.

Ứng dụng Nhà Hán Ngữ là một phần trong định hướng đó. Ứng dụng tập trung các chức năng cần thiết như bảng tin, hoạt động, biểu mẫu tham gia, hỗ trợ, quản lý hồ sơ và xác thực Giấy chứng nhận/Giấy xác nhận. Mục tiêu là giúp người dùng không phải tìm kiếm thông tin rải rác ở nhiều nơi, đồng thời giúp đội ngũ vận hành quản lý dữ liệu theo một quy trình thống nhất. Những phần dành cho cộng đồng được thiết kế đơn giản, dễ hiểu; những chức năng nghiệp vụ chuyên sâu được đặt trong khu vực quản trị.

Về nội dung, Nhà Hán Ngữ định hướng phát triển các chủ đề từ nền tảng đến nâng cao như phát âm, từ vựng, ngữ pháp, chữ Hán, kỹ năng nghe – nói – đọc – viết, kiến thức HSK, HSKK, tài liệu tham khảo liên quan đến CSCA, văn hóa Trung Hoa và các hoạt động giao lưu học tập. NHN không tự nhận là cơ quan khảo thí chính thức. Với những thông tin liên quan đến quy chế thi, lịch thi hoặc yêu cầu hồ sơ có thể thay đổi, người học vẫn nên đối chiếu nguồn chính thức trước khi đưa ra quyết định.

Nhà Hán Ngữ hướng đến nhiều nhóm người dùng: người mới bắt đầu, học sinh – sinh viên, người đang tự học, người luyện thi, người muốn cải thiện khả năng giao tiếp và cả những cá nhân muốn đóng góp kiến thức hoặc kỹ năng cho cộng đồng. Một người có thể bắt đầu bằng việc đọc một bài viết, tham gia một hoạt động, đăng ký làm cộng tác viên hoặc đơn giản là theo dõi các kênh của NHN. Không có một con đường duy nhất để trở thành một phần của cộng đồng.

NHN hoạt động trong hệ sinh thái Mạng lưới Giáo dục & Phát triển Cộng đồng Sky First (SFN). Việc có một ứng dụng riêng giúp Nhà Hán Ngữ giữ được không gian vận hành phù hợp với đặc thù của mình, nhưng vẫn có thể liên thông với hệ thống tổng hợp của Sky First khi cần. Ví dụ, API tra cứu GCN/GXN của Nhà Hán Ngữ được duy trì để hệ thống tại skyfirst.io.vn có th','published',CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO news(id,title,slug,body,status,published_at) VALUES('NEWS-CERT-2026','Tra cứu GCN/GXN: minh bạch hơn từ dữ liệu gốc','tra-cuu-gcn-gxn-du-lieu-goc','Hệ thống tra cứu GCN/GXN của Nhà Hán Ngữ được xây dựng để người dùng có thể đối chiếu nhanh một mã phát hành mà không cần liên hệ thủ công cho mỗi trường hợp. Khi nhập mã, ứng dụng truy vấn dữ liệu nguồn và trả về những trường thông tin được phép công khai như loại văn bản, người được ghi nhận, chương trình hoặc hoạt động liên quan, ngày cấp và trạng thái hiện tại. Cách làm này giúp việc xác thực thuận tiện hơn, đồng thời giảm nguy cơ sử dụng ảnh chụp hoặc bản sao không còn phù hợp với dữ liệu đang được quản lý.

Điểm quan trọng là kết quả tra cứu không dựa trên một danh sách sao chép thủ công. Nhà Hán Ngữ duy trì API công khai cho mục đích xác thực, và hệ thống tổng hợp của Sky First Network tại skyfirst.io.vn có thể đối chiếu trực tiếp qua API này. Nhờ vậy, dữ liệu vẫn được quản lý tại nguồn NHN nhưng có thể được xác thực trong hệ sinh thái SFN khi người dùng cần một điểm tra cứu tổng hợp.

Nếu một GCN/GXN bị thu hồi hoặc thay đổi trạng thái, hệ thống cần phản ánh trạng thái đó thay vì chỉ hiển thị thông tin lúc phát hành. Đây là lý do việc xác thực trực tuyến có giá trị hơn việc chỉ xem một bản ảnh. Người dùng nên sử dụng đúng mã được ghi trên văn bản và kiểm tra kỹ ký tự trước khi kết luận rằng hệ thống không có dữ liệu.

Trong trường hợp mã không trả về kết quả, bạn có thể sử dụng khu vực Hỗ trợ & phản hồi, cung cấp mã và thông tin liên quan để đội ngũ kiểm tra. Không nên công khai dữ liệu cá nhân nhạy cảm trên mạng xã hội khi yêu cầu xác minh. Với các đơn vị tích hợp, API nên được sử dụng đúng mục đích đối chiếu, không được hiểu như một cơ chế cho phép sao chép toàn bộ cơ sở dữ liệu.

Nhà Hán Ngữ xem khả năng xác thực minh bạch là một phần của trải nghiệm người dùng và trách nhiệm quản lý dữ liệu. Hệ thống sẽ tiếp tục được điều chỉnh để thông tin hiển thị vừa đủ cho việc đối chiếu, nhưng vẫn tôn trọng phạm vi dữ liệu cần được bảo vệ.','published',CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO news(id,title,slug,body,status,published_at) VALUES('NEWS-COMMUNITY-2026','Tham gia Nhà Hán Ngữ: từ người học đến người đóng góp','tham-gia-cong-dong-nha-han-ngu','Nhà Hán Ngữ không xem cộng đồng chỉ là nơi người dùng đến để nhận tài liệu. Một cộng đồng học tập có giá trị cần tạo điều kiện để mỗi người có thể tham gia theo khả năng và giai đoạn của mình. Có người muốn bắt đầu bằng việc theo dõi bài viết và hoạt động. Có người muốn luyện tập cùng những người khác. Có người có kỹ năng nội dung, truyền thông, tổ chức sự kiện hoặc thiết kế và mong muốn đóng góp cho một chương trình cụ thể.

Ứng dụng Nhà Hán Ngữ tập trung các biểu mẫu tham gia để người dùng không phải tìm đường dẫn rời rạc. Mỗi biểu mẫu có phần mô tả, nhóm thông tin cần thiết và mục đích tiếp nhận rõ ràng. Khi hồ sơ được gửi thành công, hệ thống tạo mã để người dùng có thể tra cứu tình trạng xử lý bằng email đã đăng ký. Việc này giúp quá trình tham gia minh bạch hơn và giảm phụ thuộc vào việc hỏi trạng thái qua tin nhắn cá nhân.

Đối với thành viên hoặc cộng tác viên, NHN quan tâm đến sự phù hợp với hoạt động thực tế hơn là những danh xưng hình thức. Một hồ sơ tốt nên thể hiện rõ mảng quan tâm, kỹ năng, trải nghiệm liên quan và lý do muốn tham gia. Không cần phóng đại năng lực. Thông tin chính xác giúp đội ngũ sắp xếp vai trò phù hợp hơn và cũng giúp người tham gia có trải nghiệm tốt hơn.

Trong quá trình cộng tác, các nguyên tắc cơ bản gồm tôn trọng người khác, bảo vệ dữ liệu được giao, làm việc đúng phạm vi trách nhiệm và chủ động trao đổi khi gặp khó khăn. Những tài khoản có quyền truy cập hệ thống được phân quyền theo vai trò; không phải mọi thành viên đều có quyền xem dữ liệu nội bộ. Cách tổ chức này giúp NHN vừa mở với cộng đồng vừa bảo đảm trách nhiệm trong vận hành.

Bạn có thể bắt đầu tại mục “Tham gia”, chọn biểu mẫu phù hợp và đọc kỹ thông tin trước khi gửi. Nếu chưa chắc hình thức nào phù hợp, hãy sử dụng mục Hỗ trợ để hỏi trước. Nhà Hán Ngữ mong muốn mỗi người đến với cộng đồng đều tìm được một cách tham gia thực tế, vừa sức và có giá trị.','published',CURRENT_TIMESTAMP);
